"use client";

import { useEffect, useMemo, useState } from "react";
import "./audit-management.css";
import "./guide-extra.css";

type Severity = "high" | "moderate" | "minor" | "medium" | "low";
type Project = {
  id: string; name: string; category: string; community: string; budget: number;
  contract_amount: number; status: string; progress: number; risk_count: number;
  high_risk_count: number; updated_at: string;
  is_demo?: number;
};
type Evidence = { document_id?:number; document_name: string; page: number; block_id?:number|string; bbox?:number[]; line_start?: number; line_end?: number; quote: string; parser_version_id?:number; element_ids?:string[]; lines?: { no: number; text: string; highlight: boolean }[] };
type Anomaly = { id: number; code: string; title: string; severity: Severity; summary: string; amount?: number; confidence: number; status: string; rule_kind?:string; evidences: Evidence[] };
type ProjectDocument = { id: number; name: string; doc_type: string; pages: number; source_system: string; status: string; sha256?: string; active_parser_version_id?:number; active_parser_kind?:string; active_parser_name?:string; active_parser_provider_id?:string; active_parser_version?:string; parser_status?:string; parser_stats?:Record<string,any>; parser_warnings?:string[]; parser_version_count?:number; parser_trace_run_id?:number; parser_stale?:boolean; last_audit_parser_version_id?:number };
type Detail = { project: Project; metrics: Record<string, number>; facts: Record<string, any>; anomalies: Anomaly[]; timeline: { date: string; title: string; source: string; state: string }[]; documents: ProjectDocument[] };
type AuditRunPayload = { run: any; events: any[]; calls: any[]; spans?:any[]; facts: any[]; anomalies: Anomaly[] };

const emptyProject: Project = {id:"",name:"请选择项目",category:"",community:"",budget:0,contract_amount:0,status:"未开始",progress:0,risk_count:0,high_risk_count:0,updated_at:""};

const money = (v = 0) => new Intl.NumberFormat("zh-CN", { style: "currency", currency: "CNY", maximumFractionDigits: 0 }).format(v);
const sevLabel: Record<Severity,string> = { high: "高风险", moderate:"中风险", minor:"低风险", medium: "需关注", low: "提示" };
const stageLabel:Record<string,string>={queued:'任务排队',documents:'读取原件',ocr:'MinerU OCR',document_classification:'资料分类',general_extraction:'通用字段抽取',payment_extraction:'付款台账抽取',change_extraction:'变更签证抽取',contract_extraction:'合同条款抽取',fact_persistence:'事实入库',deterministic_parser:'确定性解析',deterministic_rules:'规则计算',semantic_consistency:'语义一致性',policy_retrieval:'政策检索',text2sql:'文本转 SQL',result_summary:'结果摘要',complete:'审查完成'};
const factLabel:Record<string,string>={budget:'立项预算',max_price:'最高投标限价',award_amount:'中标金额',contract_amount:'合同金额',construction_period_days:'施工工期（天）',scope_item:'工程范围',approval_record:'审批记录',payment_record:'付款记录',settlement_record:'结算记录',acceptance_record:'验收记录',change_record:'变更记录',contract_terms:'合同条款',paid_cumulative:'累计付款',measurement_record:'计量记录'};
const factValueLabel:Record<string,string>={amount:'金额',cumulative:'累计金额',date:'日期',stage:'付款节点',payment_no:'付款编号',change_no:'变更编号',proposed_date:'提出日期',approved_date:'批准日期',implemented_date:'实施日期',attachment_summary:'附件说明',audit_date:'审定日期',audited:'审定金额',result:'结果',progress_ratio:'进度付款比例',pre_acceptance_cap:'验收前上限',post_settlement_cap:'结算后上限',change_threshold:'变更阈值'};
const factPhaseOrder=['立项审批','预算控制价','招标评标','施工合同','开工计量','变更签证','竣工验收','结算付款','其他资料','自动识别'];

export default function Home() {
  const [view, setView] = useState("dashboard");
  const [projects, setProjects] = useState<Project[]>([]);
  const [selectedId, setSelectedId] = useState("");
  const [detail, setDetail] = useState<Detail | null>(null);
  const [evidence, setEvidence] = useState<Anomaly | null>(null);
  const [query, setQuery] = useState("");
  const [severity, setSeverity] = useState("all");
  const [running, setRunning] = useState(false);
  const [toast, setToast] = useState("");
  const [apiOk, setApiOk] = useState(false);
  const [auditRun, setAuditRun] = useState<AuditRunPayload | null>(null);
  const [auditSetup, setAuditSetup] = useState(false);

  async function loadProjects() {
    try {
      const r = await fetch("/api/projects");
      if (!r.ok) throw new Error();
      const data = await r.json(); setProjects(data.items); if(data.items.length&&!data.items.some((p:Project)=>p.id===selectedId))setSelectedId(data.items[0].id); setApiOk(true);
    } catch { setApiOk(false); }
  }
  async function loadDetail(id: string) {
    try {
      const r = await fetch(`/api/projects/${id}`); if (!r.ok) throw new Error();
      setDetail(await r.json()); setApiOk(true);
      const latest=await fetch(`/api/projects/${id}/audit-runs/latest`); if(latest.ok)setAuditRun(await latest.json());
    } catch { setDetail(null); setAuditRun(null); setApiOk(false); }
  }
  useEffect(() => { loadProjects(); }, []);
  useEffect(() => { if (view === "project") loadDetail(selectedId); }, [selectedId, view]);
  useEffect(() => { if (!toast) return; const t=setTimeout(()=>setToast(""),2600); return()=>clearTimeout(t); }, [toast]);

  const visible = useMemo(() => projects.filter(p => (p.name+p.id+p.community).toLowerCase().includes(query.toLowerCase())), [projects, query]);
  const selected = detail?.project || projects.find(p=>p.id===selectedId) || emptyProject;
  const anomalies = (detail?.anomalies || []).filter(a => severity === "all" || a.severity === severity);

  function openProject(id: string) { setSelectedId(id); setView("project"); }
  function navigate(next: string) { setEvidence(null); setView(next); }
  async function runAudit(settings:Record<string,any>={}) {
    setAuditSetup(false);
    setRunning(true);
    try {
      const created=await fetch(`/api/projects/${selectedId}/audit`, { method: "POST",headers:{'Content-Type':'application/json'},body:JSON.stringify(settings) }); const body=await created.json(); if(!created.ok)throw new Error(body.detail||'创建任务失败');
      while(true){ const r=await fetch(`/api/audit-runs/${body.run_id}`); const run=await r.json(); setAuditRun(run); if(run.run.status==='completed'){await Promise.all([loadDetail(selectedId),loadProjects()]);setToast(`真实审查完成：抽取 ${run.run.fact_count} 条事实，发现 ${run.run.anomaly_count} 项待复核`);break;} if(run.run.status==='failed')throw new Error(run.run.error||'模型审查失败'); await new Promise(resolve=>setTimeout(resolve,1200)); }
    } catch(err:any) { setToast(`审查失败：${err.message||'请查看运行轨迹'}`); }
    finally { setRunning(false); }
  }

  return <div className="app-shell">
    <aside className="sidebar">
      <div className="brand"><span className="brand-mark">审</span><div><b>集智审</b><small>集体工程智能审查</small></div></div>
      <nav aria-label="主导航">
        {[['dashboard','▦','审查总览'],['projects','▤','项目台账'],['risks','◇','风险中心'],['documents','▱','资料中心'],['rules','⌘','规则与政策'],['sources','⌁','数据源管理'],['guide','?','使用说明']].map(([id,icon,label]) =>
          <button key={id} className={(view===id||(view==='project'&&id==='projects'))?'active':''} onClick={()=>setView(id)}><span>{icon}</span>{label}{id==='risks'&&projects.filter(p=>!p.is_demo).reduce((n,p)=>n+p.risk_count,0)>0&&<em>{projects.filter(p=>!p.is_demo).reduce((n,p)=>n+p.risk_count,0)}</em>}</button>)}
        <a className="trace-link" href="/trace"><span>⌁</span>开发者 Trace</a>
      </nav>
      <div className="sidebar-foot"><div className="system-state"><i className={apiOk?'online':'demo'}></i><div><b>{apiOk?'审查服务正常':'服务未连接'}</b><small>{apiOk?'文件适配器已启用 · 业务接口待接入':'等待后端启动'}</small></div></div><button className="user" onClick={()=>setToast('当前身份：工程监管岗（审查结果须人工复核）')}><span>审查</span><div><b>工程监管岗</b><small>全过程智能审查</small></div></button></div>
    </aside>
    <main>
      <header className="topbar"><div><button className="crumb" onClick={()=>navigate('dashboard')}>全过程审查</button><span>/</span><strong>{view==='project'?selected.name:'工作台'}</strong></div><div className="top-actions"><label className="search">⌕<input value={query} onChange={e=>setQuery(e.target.value)} placeholder="搜索项目、编号或社区" /></label><button className="icon-btn" aria-label="通知" onClick={()=>setToast(`当前共有 ${projects.filter(p=>!p.is_demo).reduce((n,p)=>n+p.risk_count,0)} 项真实审查结果待复核`)}>♧</button><span className="date">Real AI MVP</span></div></header>
      {view === 'dashboard' ? <Dashboard projects={visible} openProject={openProject} navigate={navigate} /> : view === 'project' ? <ProjectView project={selected} detail={detail} auditRun={auditRun} anomalies={anomalies} severity={severity} setSeverity={setSeverity} setEvidence={setEvidence} runAudit={()=>setAuditSetup(true)} running={running} back={()=>navigate('dashboard')} navigate={navigate} notify={setToast} /> : <ModuleView view={view} projects={visible} openProject={openProject} selectedId={selectedId} setSelectedId={setSelectedId} notify={setToast} refreshProjects={loadProjects} />}
    </main>
    {evidence && <EvidenceDrawerV2 anomaly={evidence} projectId={selectedId} documents={detail?.documents || []} close={()=>setEvidence(null)} notify={setToast} refreshed={()=>Promise.all([loadDetail(selectedId),loadProjects()]).then(()=>{})} />}
    {auditSetup&&<AuditSetup project={selected} documents={detail?.documents||[]} close={()=>setAuditSetup(false)} run={runAudit} notify={setToast}/>} 
    {toast && <div className="toast"><span>✓</span>{toast}</div>}
  </div>;
}

const runStageLabels:Record<string,string>={document_classification:'资料分类',general_extraction:'通用字段抽取',payment_extraction:'付款台账抽取',change_extraction:'变更签证抽取',contract_extraction:'合同条款抽取',semantic_consistency:'语义一致性',policy_retrieval:'政策查询重排',text2sql:'Text2SQL（有任务才执行）',result_summary:'结果摘要',ocr:'MinerU OCR'};
function AuditSetup({project,documents,close,run,notify}:{project:Project;documents:ProjectDocument[];close:()=>void;run:(x:Record<string,any>)=>void;notify:(x:string)=>void}){
 const [config,setConfig]=useState<any>(null);const [catalog,setCatalog]=useState<any>(null);useEffect(()=>{Promise.all([fetch('/api/providers').then(r=>r.json()),fetch('/api/review-actions/catalog').then(r=>r.json())]).then(([c,a])=>{setConfig(c);setCatalog(a)}).catch(()=>notify('审查配置读取失败'))},[]);
 const [reviewMode,setReviewMode]=useState('gate');const [actionType,setActionType]=useState('payment_approval');const [currentDocs,setCurrentDocs]=useState<number[]>([]);const [plannedAt,setPlannedAt]=useState('');const [cutoffAt,setCutoffAt]=useState(()=>{const d=new Date();d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,16)});
 const [versions,setVersions]=useState<Record<string,number>>(()=>Object.fromEntries(documents.filter(d=>d.active_parser_version_id).map(d=>[String(d.id),Number(d.active_parser_version_id)])));
 const [versionOptions,setVersionOptions]=useState<Record<string,any[]>>({});useEffect(()=>{Promise.all(documents.map(async d=>[String(d.id),(await fetch(`/api/documents/${d.id}/parser-versions`).then(r=>r.json())).items||[]] as const)).then(x=>setVersionOptions(Object.fromEntries(x))).catch(()=>notify('解析版本列表读取失败'))},[]);
 if(!config||!catalog)return <div className="simple-modal"><section className="create-project"><p>正在读取业务动作与阶段模型配置…</p></section></div>;
 function change(stage:string,key:string,value:string){setConfig({...config,stage_routes:{...config.stage_routes,[stage]:{...config.stage_routes[stage],[key]:value}}})}
 const actions=catalog.actions.filter((a:any)=>reviewMode==='gate'?!['document_increment','final_review'].includes(a.value):a.value===(reviewMode==='incremental'?'document_increment':'final_review'));
 const setMode=(mode:string)=>{setReviewMode(mode);setActionType(mode==='gate'?'payment_approval':mode==='incremental'?'document_increment':'final_review');if(mode==='final')setCurrentDocs([])};
 const needCurrent=reviewMode!=='final';
 return <div className="simple-modal audit-setup"><section><header><div><h2>提交待审业务动作</h2><p>{project.id} · 业务动作、资料截止时间、解析版本和模型路由都会固化到本次 Trace</p></div><button onClick={close}>×</button></header><div className="review-mode-panel"><h3>本次为什么审</h3><div className="review-mode-cards">{catalog.modes.map((m:any)=><button type="button" key={m.value} className={reviewMode===m.value?'active':''} onClick={()=>setMode(m.value)}><b>{m.label}</b><small>{m.description}</small></button>)}</div><div className="review-action-fields"><label>待审业务动作<select value={actionType} onChange={e=>setActionType(e.target.value)}>{actions.map((a:any)=><option key={a.value} value={a.value}>{a.label}</option>)}</select></label><label>计划办理时间<input type="datetime-local" value={plannedAt} onChange={e=>setPlannedAt(e.target.value)}/></label><label>资料截止时间<input required type="datetime-local" value={cutoffAt} onChange={e=>setCutoffAt(e.target.value)}/><small>本次运行不能看到此时间之后上传的资料，防止未来资料倒灌。</small></label></div></div><div className="audit-document-versions"><h3>{needCurrent?'资料快照：勾选本批新增/待审批资料':'资料快照：全量终审使用截止时点全部资料'}</h3>{documents.map(d=><div key={d.id}><label className="current-doc-check"><input type="checkbox" disabled={!needCurrent} checked={currentDocs.includes(d.id)} onChange={e=>setCurrentDocs(e.target.checked?[...currentDocs,d.id]:currentDocs.filter(x=>x!==d.id))}/><span><b>{d.name}</b><small>{currentDocs.includes(d.id)?'当前批次：本次重新抽取':'历史资料：有基线时复用固化事实'}</small></span></label><select value={versions[String(d.id)]||''} onChange={e=>setVersions({...versions,[String(d.id)]:Number(e.target.value)})}><option value="">请选择</option>{(versionOptions[String(d.id)]||[]).filter(v=>['ready','ready_with_warnings'].includes(v.status)).map(v=><option key={v.id} value={v.id}>文档内第 {v.document_version_no} 版 · {v.parser_name}（技术 ID {v.id}）{v.is_active?'（active）':''}</option>)}</select></div>)}</div><details className="model-route-details"><summary>模型与阶段路由（可选调整）</summary><div className="audit-route-list">{Object.entries(runStageLabels).map(([stage,label])=>{const route=config.stage_routes[stage]||{};const candidates=config.providers.filter((p:any)=>stage==='ocr'?p.kind.startsWith('mineru'):p.kind==='openai');return <div key={stage}><b>{label}</b><select value={route.provider_id||''} onChange={e=>change(stage,'provider_id',e.target.value)}>{candidates.map((p:any)=><option key={p.id} value={p.id}>{p.name}</option>)}</select><input value={route.model||''} onChange={e=>change(stage,'model',e.target.value)} placeholder="模型名"/></div>})}</div></details><footer><span>{reviewMode==='final'?'终审会检查全过程八阶段完整性。':'只检查当前动作所需前置资料，不要求未来阶段资料。'}</span><button onClick={close}>取消</button><button className="primary" disabled={documents.some(d=>!versions[String(d.id)])||needCurrent&&!currentDocs.length||!cutoffAt} onClick={()=>run({review_mode:reviewMode,action_type:actionType,planned_at:plannedAt||null,cutoff_at:cutoffAt,current_document_ids:currentDocs,route_overrides:config.stage_routes,parser_versions:versions})}>提交并开始审查</button></footer></section></div>
}

function Dashboard({projects,openProject,navigate}:{projects:Project[];openProject:(id:string)=>void;navigate:(view:string)=>void}) {
  const [dashboard,setDashboard]=useState<any>(null);
  useEffect(()=>{fetch('/api/dashboard').then(r=>r.json()).then(setDashboard).catch(()=>setDashboard(null));},[projects]);
  const production=projects.filter(p=>!p.is_demo); const risks=production.reduce((n,p)=>n+p.risk_count,0);
  const highs=production.reduce((n,p)=>n+p.high_risk_count,0);
  return <div className="page dashboard">
    <section className="hero"><div><p className="eyebrow">真实 AI 审查工作台</p><h1>当前有 <mark>{risks} 项结果</mark>需要人工复核</h1><p>只统计非示例项目最新运行中的待复核结果，不展示预置异常。</p></div><div className="hero-run"><span className="pulse">✦</span><div><b>按项目发起智能审查</b><small>阶段模型动态路由 · SQL/Python 计算 · 完整 Trace</small></div><button onClick={()=>navigate('projects')}>选择项目 →</button></div></section>
    <section className="stats">
      <Metric label="在管项目" value={String(dashboard?.counts?.projects??production.length)} unit="个" delta="示例项目不计入" tone="blue" icon="▤" />
      <Metric label="待人工复核" value={String(risks)} unit="项" delta="均关联审查运行" tone="amber" icon="◇" />
      <Metric label="高风险异常" value={String(highs)} unit="项" delta="需优先人工确认" tone="red" icon="!" />
      <Metric label="审查运行" value={String(dashboard?.counts?.runs||0)} unit="次" delta="结果可追踪到模型与证据" tone="green" icon="✓" />
    </section>
    <div className="dash-grid">
      <section className="card project-list"><div className="card-head"><div><h2>重点项目</h2><p>按风险等级和更新时间排序</p></div><button onClick={()=>navigate('projects')}>查看全部项目 →</button></div>
        <div className="table"><div className="tr th"><span>项目</span><span>合同金额</span><span>进度</span><span>风险</span><span>状态</span></div>{production.slice(0,5).map(p=><button className="tr" key={p.id} onClick={()=>openProject(p.id)}><span className="project-cell"><i>{p.category.slice(0,1)}</i><span><b>{p.name}</b><small>{p.id} · {p.community}</small></span></span><span>{money(p.contract_amount)}</span><span className="progress-cell"><i><b style={{width:`${p.progress}%`}} /></i><small>{p.progress}%</small></span><span><strong className={p.high_risk_count?'risk high':'risk'}>{p.risk_count}</strong></span><span><em className="status">{p.status}</em></span></button>)}</div>
      </section>
      <section className="card risk-panel"><div className="card-head"><div><h2>风险优先级</h2><p>最新审查或处置后自动刷新</p></div></div>
        {production.filter(p=>p.risk_count>0).slice(0,4).map(p=><button className="risk-row" key={p.id} onClick={()=>openProject(p.id)}><i className={p.high_risk_count?'high':'medium'}>!</i><span><b>{p.risk_count} 项真实审查结果待复核</b><small>{p.id} · {p.name}</small><em>{p.high_risk_count} 项高风险</em></span><time>{p.updated_at}</time></button>)}
        {!risks&&<div className="empty-state">尚无真实审查结果。进入项目并点击“开始智能审查”。</div>}
        <button className="risk-all" onClick={()=>navigate('risks')}>进入风险中心 <span>→</span></button>
      </section>
    </div>
    <section className="card source-strip"><div><span className="source-icon">⌁</span><div><h3>数据接入状态</h3><p>当前真实启用文件上传适配器；其他连接器明确显示是否配置。</p></div></div><div className="source-list"><span><i></i>项目原件<small>{dashboard?.counts?.documents||0} 份</small></span><span><i></i>累计审查事实<small>{dashboard?.counts?.facts||0} 条</small></span><span><i></i>未配置连接器<small>{dashboard?.connectors?.filter((x:any)=>x.status!=='active').length??0} 个</small></span></div><button onClick={()=>navigate('sources')}>管理连接</button></section>
  </div>
}

function Metric({label,value,unit,delta,tone,icon}:{label:string;value:string;unit:string;delta:string;tone:string;icon:string}) { return <article className="metric"><span className={`metric-icon ${tone}`}>{icon}</span><div><p>{label}</p><h2>{value}<small>{unit}</small></h2><em>{delta}</em></div></article> }

function ProjectView({project,detail,auditRun,anomalies,severity,setSeverity,setEvidence,runAudit,running,back,navigate,notify}:{project:Project;detail:Detail|null;auditRun:AuditRunPayload|null;anomalies:Anomaly[];severity:string;setSeverity:(s:string)=>void;setEvidence:(a:Anomaly)=>void;runAudit:()=>void;running:boolean;back:()=>void;navigate:(view:string)=>void;notify:(message:string)=>void}) {
 const m=detail?.metrics || {paid_amount:0,payment_rate:0,change_amount:0,change_rate:0};
 const phaseCounts=(detail?.documents||[]).reduce((acc:Record<string,number>,d)=>{acc[d.doc_type]=(acc[d.doc_type]||0)+1;return acc;},{});
 return <div className="page project-page">
   <button className="back" onClick={back}>← 返回审查总览</button>
   <section className="project-heading"><div className="project-avatar">文</div><div><div className="title-line"><h1>{project.name}</h1><em className="status">{project.status}</em>{project.is_demo?<span className="risk-tag demo">示例项目 · 不计入统计</span>:project.high_risk_count>0&&<span className="risk-tag">高风险 {project.high_risk_count}</span>}</div><p>{project.id}<i></i>{project.community}<i></i>{project.category}{project.updated_at&&<small>数据更新于 {project.updated_at}</small>}</p></div><div className="heading-actions">{auditRun?.run&&<a className="secondary report-link" href={`/trace`} target="_blank">⌁ 完整 Trace</a>}<a className="secondary report-link" href={`/api/projects/${project.id}/report`} download>↧ 导出审查报告</a><button className="primary" onClick={runAudit} disabled={running}>{running?<><span className="spinner"></span>正在交叉核验…</>:<>✦ 提交待审动作</>}</button></div></section>
   <section className="project-metrics"><div><span>项目预算</span><b>{money(project.budget)}</b><small>{detail?.facts?.budget?'审查资料已抽取':'项目建档值 · 待核验'}</small></div><div><span>合同金额</span><b>{money(project.contract_amount)}</b><small>{detail?.facts?.contract_amount?'审查资料已抽取':'项目建档值 · 待核验'}</small></div><div><span>累计变更</span><b className="amber">{money(m.change_amount)}</b><small>{auditRun?.run?.status==='completed'?`按唯一变更编号汇总 · 占比 ${(m.change_rate*100).toFixed(1)}%`:'等待审查运行'}</small></div><div><span>累计付款</span><b className="red">{money(m.paid_amount)}</b><small className="red">{auditRun?.run?.status==='completed'?`取台账最新累计值 · 付款率 ${(m.payment_rate*100).toFixed(1)}%`:'等待审查运行'}</small></div><div><span>工程进度</span><b>{project.progress}%</b><i className="wide-progress"><em style={{width:`${project.progress}%`}}></em></i></div></section>
   <section className="audit-summary"><div className={`audit-orb ${auditRun?.run?.decision_json?.status||''}`}><span>{detail?.anomalies.length || 0}</span><small>项需复核</small></div><div><h2>{auditRun?.run?.decision_json?.recommendation?`${auditRun.run.decision_json.recommendation} · ${auditRun.run.decision_json.action_label}`:auditRun?.run?`运行 #${auditRun.run.id}：${auditRun.run.status==='completed'?'审查完成':auditRun.run.status==='failed'?'审查失败':'正在执行'}`:'尚未提交待审业务动作'}</h2><p>{auditRun?.run?`资料截止 ${auditRun.run.cutoff_at||'未记录'}；读取 ${auditRun.run.result_json?.document_count||detail?.documents.length||0} 份资料，固化 ${auditRun.run.fact_count||0} 条事实。`:'上传本次业务资料后，提交付款、变更、计量或验收等待审动作。'}</p><div className="audit-legend"><span><i className="high"></i>高风险 {detail?.anomalies.filter(a=>a.severity==='high').length||0}</span><span><i className="medium"></i>新增 {auditRun?.run?.decision_json?.risk_transitions?.new||0}</span><span><i className="passed"></i>已解除 {auditRun?.run?.decision_json?.risk_transitions?.resolved||0}</span></div></div><div className="audit-meta"><span>审查模式<b>{auditRun?.run?.review_mode==='gate'?'阶段门禁':auditRun?.run?.review_mode==='incremental'?'资料增量':auditRun?.run?.review_mode==='final'?'全量终审':'未开始'}</b></span><span>模型调用<b>{auditRun?.calls?.length||0} 次</b></span><span>运行进度<b>{auditRun?.run?.progress||0}%</b></span></div></section>
   {auditRun?.run&&<RunTrace data={auditRun}/>} 
    <div className="project-grid"><section className="card anomaly-card"><div className="card-head"><div><h2>异常清单</h2><p>点击异常查看原文证据与判定依据</p></div><div className="segmented">{[['all','全部'],['high','高风险'],['moderate','中风险'],['minor','低风险'],['medium','需关注'],['low','提示']].map(x=><button key={x[0]} className={severity===x[0]?'active':''} onClick={()=>setSeverity(x[0])}>{x[1]}</button>)}</div></div>
     <div className="anomaly-list">{anomalies.map((a,i)=><button className="anomaly" key={a.id} onClick={()=>setEvidence(a)}><div className={`anomaly-no ${a.severity}`}>{String(i+1).padStart(2,'0')}</div><div className="anomaly-main"><div><em className={`pill ${a.severity}`}>{sevLabel[a.severity]}</em><span>{a.code}</span><small>置信度 {(a.confidence*100).toFixed(0)}%</small></div><h3>{a.title}</h3><p>{a.summary}</p><div className="evidence-chips">{a.evidences.slice(0,2).map((e,j)=><span key={j}>▱ {e.document_name} P{e.page}</span>)}</div></div>{a.amount && <strong className="amount">{money(a.amount)}<small>涉及金额</small></strong>}<span className="arrow">›</span></button>)}</div>
   </section><aside className="project-side"><section className="card mini-timeline"><div className="card-head"><div><h2>项目全过程</h2><p>由当次抽取记录生成</p></div><button onClick={()=>notify(`已显示 ${detail?.timeline?.length || 0} 个真实抽取节点`)}>核验节点</button></div>{detail?.timeline?.map((t,i)=><div className={`timeline-item ${t.state}`} key={i}><time>{t.date}</time><i></i><span><b>{t.title}</b><small>{t.source}</small></span></div>)}{!detail?.timeline?.length&&<div className="empty-state">完成一次智能审查后生成节点。</div>}</section>
   <section className="card doc-summary"><div className="card-head"><div><h2>项目资料</h2><p>{detail?.documents?.length || 0} 份 · {detail?.documents?.filter(d=>d.status.includes('已解析')).length||0} 份已解析</p></div><button onClick={()=>navigate('documents')}>全部资料</button></div>{['立项审批','预算控制价','招标评标','施工合同','开工计量','变更签证','竣工验收','结算付款'].map((x,i)=><button className="doc-category" key={x} onClick={()=>navigate('documents')}><span>{['立','预','招','合','计','变','验','付'][i]}</span><b>{x}</b><em>{phaseCounts[x]||0} 份</em><small>{phaseCounts[x]?'✓':'—'}</small></button>)}</section></aside></div>
 </div>
}

function RunTrace({data}:{data:AuditRunPayload}) {
 const r=data.run; const [tab,setTab]=useState('events'); const [expanded,setExpanded]=useState(false);
 const groupedFacts=useMemo(()=>{const groups:Record<string,any[]>={};for(const fact of data.facts.slice(0,240)){const phase=fact.document_type||'其他资料';(groups[phase]||(groups[phase]=[])).push(fact)}return Object.entries(groups).sort(([a],[b])=>{const ai=factPhaseOrder.indexOf(a),bi=factPhaseOrder.indexOf(b);return (ai<0?99:ai)-(bi<0?99:bi)||a.localeCompare(b,'zh-CN')})},[data.facts]);
 function factValue(value:any){if(value&&typeof value==='object'&&!Array.isArray(value))return <dl className="fact-object">{Object.entries(value).map(([key,val])=><div key={key}><dt>{factValueLabel[key]||key}</dt><dd>{typeof val==='object'?JSON.stringify(val):String(val??'—')}</dd></div>)}</dl>;return <span>{Array.isArray(value)?value.join('、'):String(value??'—')}</span>}
 return <section className={`card run-trace ${expanded?'expanded':'collapsed'}`}><div className="run-trace-head"><div><h2>AI 审查运行轨迹</h2><p>run #{r.id} · {r.provider} · {r.started_at}{r.finished_at?` → ${r.finished_at}`:''}</p></div><div className="run-progress"><a href="/trace" target="_blank">查看完整原始 I/O</a><i><b style={{width:`${r.progress||0}%`}}/></i><strong>{r.progress||0}%</strong><em className={r.status}>{r.status}</em><button className="trace-toggle" onClick={()=>setExpanded(!expanded)} aria-expanded={expanded}>{expanded?'收起':'展开'}</button></div></div>{expanded&&<>{r.error&&<div className="run-error">{r.error}</div>}<div className="trace-tabs"><button className={tab==='events'?'active':''} onClick={()=>setTab('events')}>阶段日志 {data.events.length}</button><button className={tab==='calls'?'active':''} onClick={()=>setTab('calls')}>模型调用 {data.calls.length}</button><button className={tab==='facts'?'active':''} onClick={()=>setTab('facts')}>抽取事实 {data.facts.length}</button></div>
 {tab==='events'&&<div className="event-list">{data.events.map(e=><div key={e.id}><span className={`event-state ${e.status}`}>{e.status==='completed'?'✓':e.status==='failed'?'×':'↻'}</span><b className="event-stage"><span>{stageLabel[e.stage]||'自定义阶段'}</span><code title={e.stage}>{e.stage}</code></b><p>{e.message}</p><time>{e.created_at}</time></div>)}</div>}
 {tab==='calls'&&<div className="call-list">{data.calls.map(c=><div key={c.id}><span className="model-badge">{c.provider}</span><div><b>{c.stage} · {c.model}</b><p>{c.success?'调用成功':`失败：${c.error}`} · {c.duration_ms}ms · 输入 {c.input_tokens??'—'} / 输出 {c.output_tokens??'—'} tokens</p><small>request hash {c.request_hash?.slice(0,16)}…</small></div></div>)}{!data.calls.length&&<p className="empty-state">模型调用尚未开始。</p>}</div>}
 {tab==='facts'&&<div className="fact-groups">{groupedFacts.map(([phase,facts])=><section className="fact-group" key={phase}><header><div><span>{phase.slice(0,1)}</span><b>{phase}</b></div><small>{facts.length} 条事实</small></header><div className="fact-grid">{facts.map(f=><article key={f.id}><div className="fact-field"><b>{factLabel[f.field_name]||'自定义事实'}</b><code>{f.field_name}</code></div><div className="fact-value">{factValue(f.value_json)}</div><small>{f.document_name} · P{f.page||1}{f.block_id?` · B${f.block_id}`:''} · 置信度 {(f.confidence*100).toFixed(0)}% · {f.provider}</small>{f.quote&&<q>{f.quote}</q>}</article>)}</div></section>)}{!data.facts.length&&<p className="empty-state">尚未产生结构化事实。</p>}</div>}
 </> }</section>
}

function EvidenceDrawerV2({anomaly,projectId,documents,close,notify,refreshed}:{anomaly:Anomaly;projectId:string;documents:ProjectDocument[];close:()=>void;notify:(message:string)=>void;refreshed:()=>void}) {
 const [tab,setTab]=useState(0); const [zoom,setZoom]=useState(100); const [saving,setSaving]=useState(false); const [location,setLocation]=useState<any>(null); const [loading,setLoading]=useState(false);
 const evidence=anomaly.evidences[tab]; const original=evidence?documents.find(d=>d.id===evidence.document_id)||documents.find(d=>d.name===evidence.document_name):undefined;
 useEffect(()=>{let cancelled=false;if(!evidence||!original){setLocation(null);return;}const params=new URLSearchParams({page:String(evidence.page||1),quote:evidence.quote||''});if(evidence.parser_version_id)params.set('parser_version_id',String(evidence.parser_version_id));if(evidence.element_ids?.[0])params.set('element_id',evidence.element_ids[0]);setLoading(true);fetch(`/api/documents/${original.id}/evidence-location?${params}`).then(r=>r.ok?r.json():Promise.reject()).then(x=>!cancelled&&setLocation(x)).catch(()=>!cancelled&&setLocation(null)).finally(()=>!cancelled&&setLoading(false));return()=>{cancelled=true};},[tab,anomaly.id,original?.id,evidence?.parser_version_id,evidence?.element_ids?.[0]]);
 async function setStatus(status:string){setSaving(true);try{const r=await fetch(`/api/anomalies/${anomaly.id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status})});if(!r.ok)throw new Error();notify(`异常已更新为“${status}”`);refreshed();close();}catch{notify('处理状态保存失败，请检查服务');}finally{setSaving(false);}}
 const loc=location?.location; const box=loc?.bbox; const width=loc?.page_width; const height=loc?.page_height; const highlight=box&&width&&height?{left:`${box[0]/width*100}%`,top:`${box[1]/height*100}%`,width:`${(box[2]-box[0])/width*100}%`,height:`${(box[3]-box[1])/height*100}%`}:null;
 return <div className="drawer-wrap" onMouseDown={x=>x.target===x.currentTarget&&close()}><aside className="drawer"><header><div><em className={`pill ${anomaly.severity}`}>{sevLabel[anomaly.severity]}</em><h2>{anomaly.title}</h2><p>{anomaly.code} · {projectId} · AI置信度 {(anomaly.confidence*100).toFixed(0)}% · 当前状态：{anomaly.status}</p></div><button onClick={close} aria-label="关闭证据">×</button></header><section className="reason"><span>✦</span><div><b>智能判定说明</b><p>{anomaly.summary}</p></div></section>
 {anomaly.evidences.length===0?<section className="no-document-evidence"><b>这是资料完整性规则结果</b><p>该异常表示系统未找到要求的资料类别，因此不存在可以高亮的原件页面。请到资料中心补充缺失资料后重新审查。</p></section>:<><nav>{anomaly.evidences.map((x,i)=><button className={tab===i?'active':''} onClick={()=>setTab(i)} key={i}><span>证据 {i+1}</span><b>{x.document_name}</b><small>第 {x.page} 页{x.element_ids?.[0]?` · 元素 ${x.element_ids[0]}`:x.block_id?` · 版面块 ${x.block_id}`:''}</small></button>)}</nav><div className="doc-toolbar"><span>▱ {evidence.document_name}</span><div><button onClick={()=>setZoom(v=>Math.max(70,v-10))}>−</button><em>{zoom}%</em><button onClick={()=>setZoom(v=>Math.min(180,v+10))}>＋</button>{original&&<a href={`/api/documents/${original.id}/download`} target="_blank" rel="noreferrer">↗ 打开原件</a>}</div></div><div className="original-preview">{loading?<div className="preview-loading">正在按固化解析版本定位原文元素…</div>:location?.is_original_page?<div className="pdf-page-image" style={{width:`${zoom}%`}}><img src={location.render_url} alt={`${evidence.document_name} 第${location.page}页原件`}/>{highlight&&<span className="coordinate-highlight" style={highlight}><i>证据</i></span>}</div>:<div className="preview-loading">该格式暂不支持页面图像渲染，请打开原件核验。</div>}</div><section className="quote-proof"><b>审查引用原文</b><q>{evidence.quote}</q><small>{loc?`已在真实第 ${location.page} 页元素 ${loc.block_id} 定位 · 解析版本 #${location.parser_version_id||'legacy'} · 坐标来源 ${location.coordinate_source}`:'该元素没有可信坐标，不生成模拟高亮；请打开原件人工定位'}</small></section></>}
 <section className="trace"><h3>判定依据</h3><div><span>规则</span><p>{anomaly.rule_kind||'规则与语义交叉核验'} <b>{anomaly.code}</b></p></div><div><span>预览</span><p>原始 PDF 页面服务端渲染；黄色框为解析版面坐标叠加，不重排原文。</p></div><div><span>溯源</span><p>文档原件、SHA256、审查运行、模型事实与坐标可追溯。</p></div></section><footer className="drawer-actions"><button disabled={saving} onClick={()=>setStatus('误报')}>标记为误报</button><button disabled={saving} onClick={()=>setStatus('已转交')}>转交处理</button><button disabled={saving} className="primary" onClick={()=>setStatus('已确认')}>确认异常</button></footer></aside></div>;
}

function ModuleView({view,projects,openProject,selectedId,setSelectedId,notify,refreshProjects}:{view:string;projects:Project[];openProject:(id:string)=>void;selectedId:string;setSelectedId:(id:string)=>void;notify:(message:string)=>void;refreshProjects:()=>Promise<void>}) {
  if(view==='guide') return <GuideView openProject={openProject} projects={projects}/>;
  if(view==='documents') return <DocumentsCenter projects={projects} selectedId={selectedId} setSelectedId={setSelectedId} notify={notify} />;
  if(view==='sources') return <SourcesCenter notify={notify} />;
  if(view==='risks') return <RiskCenter openProject={openProject} />;
  if(view==='rules') return <RulesCenter notify={notify} />;
  return <ProjectLedger projects={projects} openProject={openProject} notify={notify} refreshProjects={refreshProjects} />;
}

function GuideView({openProject,projects}:{openProject:(id:string)=>void;projects:Project[]}) {
 const firstReal=projects.find(p=>!p.is_demo);
 return <div className="page module-page guide-page guide-v2"><div className="guide-hero"><span>使用说明 · Real AI MVP</span><h1>从资料解析、真实审查到可复现调试</h1><p>每次运行固化资料版本、Prompt 版本、模型路由和完整输入输出。调试实验永远创建新 Trace，不覆盖历史运行。</p>{firstReal&&<button className="primary" onClick={()=>openProject(firstReal.id)}>打开非示例项目开始 →</button>}</div>
 <section className="guide-steps">{[['01','配置模型','在 /trace 的“模型配置”中填写显示名称、Base URL、Model ID 与可选 API Key；先测试连接，再保存添加。'],['02','上传并解析','上传时人工选择 PyMuPDF、云端 MinerU 或本地 MinerU；默认在解析完成后自动设为 active，也可关闭自动切换。'],['03','提交待审动作','默认选择阶段门禁，指定付款、变更、计量、验收等动作，勾选本批资料并固化资料截止时间；完工后才选全量终审。'],['04','核查放行依据','结果区分建议放行、附条件放行和暂缓审批，并显示风险新增、持续、解除；证据回到真实 PDF 页面高亮。'],['05','进入 Trace 调试','从项目运行轨迹点“查看完整 I/O”，核对业务动作快照、截止时间、当前/历史资料角色、基线事实复用和每个 span。']].map(x=><article className="card" key={x[0]}><em>{x[0]}</em><h2>{x[1]}</h2><p>{x[2]}</p></article>)}</section>
 <section className="card guide-identifiers"><h2>三种审查模式怎样选择</h2><p><b>阶段门禁</b>用于一个具体动作批准前：付款、变更、计量、验收等，只检查当前动作所需前置资料，不会因尚未发生竣工或结算而报“全过程不完整”。</p><p><b>新增资料增量审查</b>用于施工日志、送货单、检测报告等日常批次到达；有历史基线时仅重新抽取本批资料，并复用截止时点之前的固化历史事实。<b>全过程全量终审</b>用于竣工结算、年度内控或历史项目审计，此时才检查八阶段资料完整性。</p><p>资料截止时间是不可复现问题的边界：后续补传资料不能倒灌到历史运行。每次 Trace 都保存待审动作、当前批次、历史资料、基线 Run、适用规则和不适用规则。</p></section>
 <section className="card guide-identifiers"><h2>为什么序号曾经看起来是全局共用？</h2><p><b>数据库中的 Run ID、解析版本 ID 是全局唯一技术主键，这是有意设计。</b>它让 API、外键、父子派生链、证据快照和导出文件都能用一个永不歧义的编号定位对象。它不是项目内的业务次数。</p><p>之前页面直接把技术 ID 写成“Run #100”“version #100”，却没有同时显示业务内序号，这是展示设计缺陷。现在 Trace 显示“项目内第 N 次 + 技术 Run ID”，解析版本显示“文档内第 N 版 + 技术版本 ID”。业务内序号同样会在创建时固化，删除历史条目后保留空档，不会让后来记录悄悄改号；所有持久引用仍只认不可复用的技术 ID。</p></section>
 <section className="card trace-howto"><header><div><h2>手把手：某个环节输出可疑时怎样换模型调试</h2><p>下面以“合同条款抽取结果可疑，想换一个模型比较”为例。</p></div><a href="/trace">打开开发者 Trace ↗</a></header><ol><li><b>定位源运行。</b>左侧先选项目，再选产生当前正式结果的审查运行。列表同时显示项目内次数、技术 Run ID、类型和时间，优先选择 run_kind 为 audit 的运行。</li><li><b>定位可疑调用。</b>在“执行顺序”选择“合同条款抽取”，再选其下具体的 <code>model_call</code>。容器 stage、确定性规则或 OCR 本身没有可重放的模型输入，按钮会禁用。</li><li><b>先读完整输入。</b>展开“完整输入”，核对 system prompt、user prompt、messages、prompt_variables、structured output schema、输入文档块和 max_tokens；再对照“完整输出”和 Span 元数据中的 provider、model、耗时、状态。先判断问题来自资料、Prompt、模型还是下游规则。</li><li><b>选择实验模型。</b>在该 span 上方的“本次实验使用模型”和“Model ID”中选另一个已保存模型。此选择只写入新实验 Run 的 route_overrides，不改源 Run，也不必先改全局默认路由。若列表没有目标模型，先到“模型配置”执行添加 → 测试连接 → 保存。</li><li><b>选择实验范围。</b>只想比较同一输入在另一模型下的输出，点“仅测试此阶段”；想观察变化沿后续模型环节传播，点“从此阶段派生模型链”。</li><li><b>检查新 Trace。</b>系统自动跳到新运行。核对它的 parent_run_id、derived_from_stage、route_overrides、完整输入输出和结果；源运行保持不变，可来回切换比较。</li><li><b>决定是否正式采用。</b>实验满意后，回到项目重新点击“发起智能审查”，在表单里为相应阶段选定模型并完成一次完整审查。只有完整审查才会重新固化事实、执行规则、生成异常并更新项目。</li></ol></section>
 <section className="guide-debug-compare"><article className="card"><em>PROBE</em><h2>仅测试此阶段</h2><ul><li>使用源 Trace 保存的精确输入与源运行 Prompt 快照。</li><li>在当前 MVP 中只重放该阶段按顺序找到的第一个 <code>model_call</code>。</li><li>不执行下游模型、规则、事实固化和异常生成。</li><li>适合低成本判断“是不是模型本身导致输出差异”。</li></ul></article><article className="card"><em>DERIVED</em><h2>从此阶段派生模型链</h2><ul><li>此阶段之前复用不可变上游快照。</li><li>此阶段及后续已有的模型调用使用当前已发布 Prompt 与所选/当前模型重新执行。</li><li>一个阶段有多份文档调用时，会按源 Trace 重放该阶段全部模型调用。</li><li>当前不会重提 OCR，也不会回写项目事实、规则结果或异常；它是分支影响实验，不是正式复审。</li></ul></article><article className="card"><em>FULL AUDIT</em><h2>重新完整审查</h2><ul><li>使用表单选择的 active/指定解析版本、Prompt 和阶段模型建立全新正式 Run。</li><li>执行抽取、语义判断、政策检索、确定性规则、事实与异常固化。</li><li>会更新项目当前审查结果，是正式采用实验结论的唯一入口。</li><li>旧 Run 仍永久保留，除非在 Trace 控制台明确永久删除。</li></ul></article></section>
 <div className="guide-grid"><section className="card"><h2>解析与证据的当前规则</h2><dl><dt>PyMuPDF</dt><dd>保留为人工可选的文字版面方案，不再默认抢占 active。</dd><dt>云端 / 本地 MinerU</dt><dd>页面明确区分来源；消费结构化 element、list_items、表格 HTML/Markdown、视觉资源、页码和坐标。解析版本不可修改，可对比、派生规范化版本或在未被引用时删除。</dd><dt>页码与坐标</dt><dd>Markdown 用于下游语义，JSON 元素用于 element_id、page、bbox 和原文高亮；两者都保留，不能用换行硬拆替代结构。</dd></dl></section><section className="card"><h2>Prompt、模型与调试边界</h2><p>发布版 Prompt 不可修改；要调整先复制为草稿、测试、再发布。每次正式或实验运行都固化 prompt_version 和模型配置快照。</p><p>视觉 model_call 可以做“仅测试此阶段”，当前不进入派生模型链。若源运行该阶段没有 model_call，派生时会留空/跳过。</p><p>/trace 暂无访问保护，供应商密钥按 MVP 约定明文保存在工作站配置文件；只能部署在可信内网，禁止直接暴露互联网。</p></section></div></div>
}

function LegacyGuideView({openProject,projects}:{openProject:(id:string)=>void;projects:Project[]}) {
 return <div className="page module-page guide-page"><div className="guide-hero"><span>使用说明 · Real AI MVP</span><h1>从新建项目到可复现的证据审查</h1><p>系统不读取预置异常或验收真值作为答案。每次结论来自当次资料、发布版 Prompt、阶段模型、确定性规则与政策检索，并固化完整 run。</p>{projects.find(p=>!p.is_demo)&&<button className="primary" onClick={()=>openProject(projects.find(p=>!p.is_demo)!.id)}>打开非示例项目开始 →</button>}</div>
 <section className="guide-steps">{[['01','创建空白项目','项目建档值与 AI 抽取事实严格分开；示例项目带徽标且不计入统计。'],['02','上传并选择解析方案','每批资料人工选择 PyMuPDF 或 MinerU；二者创建独立、不可变且可对比的解析版本。'],['03','确认 active 与运行版本','MinerU 完成后不会自动替换 active；发起审查时再逐份确认本次固化的解析版本。'],['04','打开 /trace','解析 run 和审查 run 均按项目保存完整输入输出、原始产物、结构化结果、校验和规则过程。'],['05','人工复核证据','证据按 parser_version + element_id 回到原始 PDF 坐标；无可信坐标时不生成模拟高亮。']].map(x=><article className="card" key={x[0]}><em>{x[0]}</em><h2>{x[1]}</h2><p>{x[2]}</p></article>)}</section>
 <div className="guide-grid"><section className="card"><h2>两种解析方案</h2><dl><dt>PyMuPDF 文字版面解析</dt><dd>保留旧方案，适合有文本层的 PDF；输出段落块、页码和真实坐标，解析在本机完成。</dd><dt>MinerU 高级视觉解析</dt><dd>完整保留 content_list、图片资源和 ZIP；统一映射标题、段落、表格、图像、图表、公式、印章、签名、手写和表单等元素。表格优先消费 MinerU HTML/Markdown 并转为单元格 JSON。</dd><dt>多模态 LLM</dt><dd>仅对 MinerU 产出的真实视觉资源做分类型复核；图片摘要、图表、印章签名、表单手写分别路由，原始请求与结构化输出进入解析 Trace。</dd><dt>下游审查</dt><dd>LLM 按结构化 chunk 和稳定 element_id 抽取；SQL/Python 直接消费表格单元格，证据绑定解析版本与元素坐标。</dd></dl></section><section className="card"><h2>开发者调试</h2><p>主导航“开发者 Trace”进入独立控制台。解析和审查都是独立 run；支持完整 JSON/原件包导出、永久删除、阶段重放、模型配置和 Prompt 管理。</p><p>大于 256KB 的 trace 工件会 gzip 落盘并记录 SHA256；MinerU 原始 ZIP 可从解析版本页单独下载。</p><h2>版本原则</h2><p>解析版本创建后不可修改，active 只影响未来默认选择；每次审查仍会固化逐份资料的 parser_version_id，历史结果可复现。</p><h2>MVP 安全边界</h2><p>/trace 暂无访问保护，供应商密钥明文保存在本机后端配置文件。系统必须只部署在可信内网，切勿直接暴露到互联网。</p></section></div>
 </div>
}

function ProjectLedger({projects,openProject,notify,refreshProjects}:{projects:Project[];openProject:(id:string)=>void;notify:(message:string)=>void;refreshProjects:()=>Promise<void>}) {
 const [creating,setCreating]=useState(false); const [saving,setSaving]=useState(false);
 async function create(e:any){e.preventDefault();const f=e.currentTarget;const data={id:f.project_id.value,name:f.project_name.value,community:f.community.value,category:f.category.value,budget:Number(f.budget.value),contract_amount:Number(f.contract_amount.value||0),status:f.status.value,progress:Number(f.progress.value||0),with_demo_materials:f.with_demo_materials.checked};setSaving(true);try{const r=await fetch('/api/projects',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const result=await r.json();if(!r.ok)throw new Error(result.detail);await refreshProjects();setCreating(false);notify(`项目 ${result.project_id} 已创建，生成 ${result.documents_created} 份资料`);openProject(result.project_id);}catch(err:any){notify(`新建失败：${err.message||'未知错误'}`);}finally{setSaving(false);}}
 async function remove(p:Project){if(!window.confirm(`确定删除项目“${p.name}”（${p.id}）吗？\n\n项目、完整 Trace、事实、异常和解析结构将永久删除；仅原始文件会移入服务器 trash 目录，不能一键恢复整个项目。`))return;try{const r=await fetch(`/api/projects/${p.id}?confirm=${encodeURIComponent(p.id)}`,{method:'DELETE'});const result=await r.json();if(!r.ok)throw new Error(result.detail);await refreshProjects();notify(`项目已删除：${result.trace_runs_deleted} 个 Trace 永久删除；${result.original_files_recoverable?'原件已移入 trash':'没有原件目录'}`);}catch(err:any){notify(`删除失败：${err.message||'未知错误'}`);}}
 return <div className="page module-page"><div className="module-title-row"><div><h1>项目台账</h1><p>新建项目默认为空白项目；示例项目隔离显示且不计入风险与首页统计。</p></div><button onClick={async()=>{const d=await fetch('/api/demo/install',{method:'POST'}).then(r=>r.json());await refreshProjects();notify(d.installed?`已安装 ${d.installed} 个隔离示例项目`:'示例项目已经存在')}}>安装示例项目</button><button className="primary" onClick={()=>setCreating(true)}>＋ 新建项目</button></div><section className="card project-crud"><div className="card-head"><h2>全部工程项目</h2><span className="table-count">共 {projects.length} 个项目</span></div>{projects.map(p=><div className="project-crud-row" key={p.id}><button className="project-open" onClick={()=>openProject(p.id)}><span><b>{p.name} {p.is_demo?<em className="demo-badge">示例</em>:''}</b><small>{p.id} · {p.community}</small></span><span>{p.contract_amount?money(p.contract_amount):'待合同资料核验'}</span><span><em className={p.high_risk_count?'pill high':'pill medium'}>{p.risk_count} 项待复核</em></span><span>{p.progress}%</span><i>查看 ›</i></button><button className="delete-project" onClick={()=>remove(p)} aria-label={`删除项目 ${p.id}`}>删除</button></div>)}</section>
 {creating&&<div className="simple-modal"><section className="create-project"><header><div><h2>新建工程项目</h2><p>创建后可进入项目、上传资料并运行全过程审查</p></div><button onClick={()=>setCreating(false)} aria-label="关闭">×</button></header><form onSubmit={create}><label>项目编号<input name="project_id" required placeholder="例如 TEST-2026-001" pattern="[A-Za-z0-9_-]{4,32}"/></label><label>项目名称<input name="project_name" required placeholder="例如 社区文化活动中心改造工程"/></label><label>所属社区<input name="community" required placeholder="例如 某某社区"/></label><label>工程类别<select name="category"><option>公共设施</option><option>市政工程</option><option>改造工程</option><option>装修工程</option><option>修缮工程</option><option>设备采购</option><option>绿化工程</option></select></label><label>立项预算（元）<input name="budget" type="number" min="1" required placeholder="请输入立项预算"/></label><label>合同金额（元，可空）<input name="contract_amount" type="number" min="0" placeholder="未知时保持 0，不会自动等于预算"/></label><label>项目状态<select name="status"><option>立项审批</option><option>招标中</option><option>合同签订</option><option>施工中</option><option>待验收</option><option>已完工</option></select></label><label>当前进度（%）<input name="progress" type="number" min="0" max="100" defaultValue="0"/></label><label className="demo-check"><input name="with_demo_materials" type="checkbox"/><span><b>可选：生成隔离演示原件</b><small>项目将标记为示例，不计入任何业务统计。</small></span></label><footer><button type="button" onClick={()=>setCreating(false)}>取消</button><button className="primary" disabled={saving}>{saving?'正在创建…':'创建并进入项目'}</button></footer></form></section></div>}</div>
}

function DocumentsCenter({projects,selectedId,setSelectedId,notify}:{projects:Project[];selectedId:string;setSelectedId:(id:string)=>void;notify:(message:string)=>void}) {
 const [docs,setDocs]=useState<ProjectDocument[]>([]); const [projectName,setProjectName]=useState(''); const [preview,setPreview]=useState<any>(null); const [previewPage,setPreviewPage]=useState(1); const [loading,setLoading]=useState(true); const [uploading,setUploading]=useState(false); const [parseMode,setParseMode]=useState(''); const [versionDoc,setVersionDoc]=useState<ProjectDocument|null>(null); const [ocrProviders,setOcrProviders]=useState<any[]>([]); const [ocrProviderId,setOcrProviderId]=useState(''); const [autoActivate,setAutoActivate]=useState(true);
 async function load(){ setLoading(true); try{const r=await fetch(`/api/projects/${selectedId}`);const d=await r.json();setDocs(d.documents||[]);setProjectName(d.project?.name||selectedId);}catch{setDocs([]);}finally{setLoading(false);} }
 useEffect(()=>{load();},[selectedId]);
 useEffect(()=>{fetch('/api/providers').then(r=>r.json()).then(d=>{const providers=(d.providers||[]).filter((p:any)=>p.kind?.startsWith('mineru')&&p.enabled);setOcrProviders(providers);const preferred=d.stage_routes?.ocr?.provider_id;setOcrProviderId(providers.some((p:any)=>p.id===preferred)?preferred:(providers[0]?.id||''));}).catch(()=>setOcrProviders([]));},[]);
 async function inspect(id:number){ const r=await fetch(`/api/documents/${id}`); if(r.ok){setPreview(await r.json());setPreviewPage(1);} else notify('资料读取失败'); }
 async function upload(e:any){ e.preventDefault(); const form=e.currentTarget; const input=form.elements.namedItem('file') as HTMLInputElement; const files=Array.from(input.files||[]); if(!files.length){notify('请先选择文件');return;}if(!parseMode){notify('请先人工选择本批资料的解析方案');return;}if(parseMode==='mineru'&&!ocrProviderId){notify('请选择云端或本地 MinerU');return;}setUploading(true);try{const body=new FormData();body.append('project_id',selectedId);body.append('doc_type',form.elements.namedItem('doc_type').value);body.append('source_system','文件上传适配器');body.append('parse_mode',parseMode);body.append('auto_activate',String(autoActivate));if(parseMode==='mineru'){const provider=ocrProviders.find(p=>p.id===ocrProviderId);body.append('parser_provider_id',ocrProviderId);body.append('parser_model',provider?.kind==='mineru-local'?'vlm-engine':(provider?.models?.[0]||'vlm'));}for(const file of files)body.append('files',file as File);const r=await fetch('/api/documents/upload-batch',{method:'POST',body});const d=await r.json();if(!r.ok)throw new Error(d.detail||'批量上传失败');const skipped=(d.items||[]).filter((x:any)=>x.duplicate).length;const provider=ocrProviders.find(p=>p.id===ocrProviderId);notify(`${parseMode==='mineru'?`${provider?.name||'MinerU'} 批量任务已提交`:'PyMuPDF 解析完成'}：${d.total} 份${autoActivate?'，完成后自动设为 active':''}${skipped?`，其中重复资料 ${skipped} 份`:''}`);form.reset();setParseMode('');await load();}catch(err:any){notify(`上传失败：${err.message||'未知错误'}`);await load();}finally{setUploading(false);} }
 async function remove(d:ProjectDocument){if(!window.confirm(`确定删除资料“${d.name}”吗？原件将移入服务器回收目录。`))return;const r=await fetch(`/api/documents/${d.id}`,{method:'DELETE'});const result=await r.json();if(!r.ok){notify(`删除失败：${result.detail}`);return;}notify(`已删除 ${d.name}，原件已移入回收目录`);await load();}
 return <div className="page module-page"><div className="module-title-row"><div><h1>资料中心</h1><p>上传时人工选择解析方案；原件与不可变解析版本分别保存，审查运行只引用已固化版本。</p></div><label className="project-select">当前项目<select value={selectedId} onChange={e=>setSelectedId(e.target.value)}>{projects.map(p=><option key={p.id} value={p.id}>{p.id} · {p.name}</option>)}</select></label></div>
 <form className="card versioned-upload" onSubmit={upload}><header><div><b>批量上传待审资料</b><small>先选择本批解析器；系统不再默认执行 PyMuPDF。</small></div><select name="doc_type" aria-label="资料类型"><option>自动识别</option>{['立项审批','预算控制价','招标评标','施工合同','开工计量','变更签证','竣工验收','结算付款','其他资料'].map(x=><option key={x}>{x}</option>)}</select></header><div className="parser-choice"><button type="button" className={parseMode==='pymupdf'?'active':''} onClick={()=>setParseMode('pymupdf')}><b>PyMuPDF 文字版面解析</b><small>适合可复制文本 PDF；仅在人工选择时执行。</small><em>文字版面 · 本地执行</em></button><button type="button" className={parseMode==='mineru'?'active':''} onClick={()=>setParseMode('mineru')}><b>MinerU 视觉解析</b><small>识别标题、表格、图片、图表、公式、印章等结构。</small><em>选择后再指定云端或本地 VLM</em></button></div>{parseMode==='mineru'&&<label className="mineru-provider-choice">MinerU 执行端<select value={ocrProviderId} onChange={e=>setOcrProviderId(e.target.value)}>{ocrProviders.map(p=><option key={p.id} value={p.id}>{p.kind==='mineru-local'?'本地 MinerU 视觉解析（VLM）':'云端 MinerU 视觉解析'} · {p.name} · {p.kind==='mineru-local'?'vlm-engine':(p.models?.[0]||'vlm')}</option>)}</select></label>}<label className="auto-active-choice"><input type="checkbox" checked={autoActivate} onChange={e=>setAutoActivate(e.target.checked)}/><span><b>解析完成后自动设为 active</b><small>默认开启；本批选择哪个解析器，就直接成为后续审查默认输入。</small></span></label><footer><input name="file" type="file" multiple accept=".pdf,.docx,.txt,.png,.jpg,.jpeg,.webp,.bmp" aria-label="选择一个或多个资料文件"/><button className="primary" disabled={uploading||!parseMode||(parseMode==='mineru'&&!ocrProviderId)}>{uploading?'正在上传/提交…':parseMode?'上传并创建解析版本':'先选择解析方案'}</button></footer></form>
 <section className="card document-table parser-document-table"><div className="card-head"><div><h2>{projectName || selectedId}</h2><p>{loading?'正在加载…':`${docs.length} 份归档资料 · active 版本决定后续默认审查输入`}</p></div></div><div className="doc-th"><span>资料名称</span><span>标准阶段</span><span>当前解析版本</span><span>结构统计</span><span>操作</span></div>{docs.map(d=><div className="doc-row" key={d.id}><span className="doc-name"><i>{d.name.toLowerCase().endsWith('.pdf')?'PDF':'DOC'}</i><span><b>{d.name}</b><small>{d.pages} 页 · SHA256 {d.sha256?.slice(0,10) || '已固化'}…</small></span></span><span>{d.doc_type}<small>{d.source_system}</small></span><span><em className={d.parser_status==='ready'||d.parser_status==='ready_with_warnings'?'parsed':'pending'}>{d.active_parser_kind==='mineru'?(d.active_parser_provider_id?.includes('local')?'MinerU 本地视觉解析（VLM）':'MinerU 云端视觉解析'):(d.active_parser_name||'尚未选择 active 版本')}</em><small>version #{d.active_parser_version_id||'—'} · 共 {d.parser_version_count||0} 版{d.parser_stale?' · 审查结果已过期':''}</small></span><span><b>{d.parser_stats?.elements||0}</b> 元素 · <b>{d.parser_stats?.tables||0}</b> 表格<small>{d.parser_stats?.coordinate_elements||0} 个坐标 · {d.parser_stats?.visual_elements||0} 个视觉元素</small></span><span className="doc-actions"><button onClick={()=>setVersionDoc(d)}>解析版本</button><button onClick={()=>inspect(d.id)}>预览原件</button><a href={`/api/documents/${d.id}/download`} target="_blank" rel="noreferrer">原件 ↗</a><button className="danger" onClick={()=>remove(d)}>删除</button></span></div>)}{!loading&&!docs.length&&<div className="empty-state">该项目尚未上传资料。</div>}</section>
 {preview&&<div className="simple-modal document-preview-modal" onMouseDown={e=>e.target===e.currentTarget&&setPreview(null)}><section><header><div><h2>{preview.name}</h2><p>{preview.doc_type} · {preview.source_system} · {preview.pages} 页 · 解析器 {preview.content?.extractor}</p></div><button onClick={()=>setPreview(null)}>×</button></header><div className="document-page-preview"><img src={`/api/documents/${preview.id}/pages/${previewPage}/render`} alt={`${preview.name} 第${previewPage}页原件`}/></div><footer><button disabled={previewPage<=1} onClick={()=>setPreviewPage((x:number)=>Math.max(1,x-1))}>上一页</button><span>第 {previewPage} / {preview.pages} 页</span><button disabled={previewPage>=preview.pages} onClick={()=>setPreviewPage((x:number)=>Math.min(preview.pages,x+1))}>下一页</button><a className="primary" href={preview.download_url} target="_blank" rel="noreferrer">打开完整原件</a><button onClick={()=>setPreview(null)}>关闭</button></footer></section></div>}
 {versionDoc&&<ParserVersionManager document={versionDoc} close={()=>setVersionDoc(null)} notify={notify} refreshed={load}/>}</div>
}

function ParserVersionManager({document,close,notify,refreshed}:{document:ProjectDocument;close:()=>void;notify:(x:string)=>void;refreshed:()=>Promise<void>}){
 const [items,setItems]=useState<any[]>([]);const [loading,setLoading]=useState(true);const [busy,setBusy]=useState('');const [left,setLeft]=useState<number>();const [right,setRight]=useState<number>();const [comparison,setComparison]=useState<any>(null);const [ocrProviders,setOcrProviders]=useState<any[]>([]);
 async function load(){const r=await fetch(`/api/documents/${document.id}/parser-versions`);const d=await r.json();setItems(d.items||[]);setLoading(false);if(!left&&d.items?.[0])setLeft(d.items[0].id);if(!right&&d.items?.[1])setRight(d.items[1].id)}
 useEffect(()=>{load();const timer=setInterval(()=>{if(items.some(v=>['queued','submitted','running','visual_analyzing'].includes(v.status)))load()},3000);return()=>clearInterval(timer)},[document.id,items.map(v=>`${v.id}:${v.status}`).join('|')]);
 useEffect(()=>{fetch('/api/providers').then(r=>r.json()).then(d=>setOcrProviders((d.providers||[]).filter((p:any)=>p.kind?.startsWith('mineru')&&p.enabled))).catch(()=>setOcrProviders([]));},[]);
 async function create(kind:string,provider?:any){const key=provider?.id||kind;setBusy(key);const r=await fetch(`/api/documents/${document.id}/parser-versions`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({parser_kind:kind,force:true,provider_id:provider?.id,model:provider?.kind==='mineru-local'?'vlm-engine':provider?.models?.[0],auto_activate:true})});const d=await r.json();setBusy('');if(!r.ok)return notify(d.detail||'创建解析版本失败');notify(kind==='mineru'?`${provider?.name||'MinerU'} 新版本已提交，完成后自动设为 active`:'PyMuPDF 新版本已完成');await load();await refreshed()}
 async function activate(id:number){setBusy(`active-${id}`);const r=await fetch(`/api/documents/${document.id}/active-parser-version`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({parser_version_id:id})});const d=await r.json();setBusy('');if(!r.ok)return notify(d.detail||'切换失败');notify(`已将解析版本 #${id} 设为 active；历史审查不会被改写`);await load();await refreshed()}
 async function renormalize(v:any){setBusy(`normalize-${v.id}`);const r=await fetch(`/api/parser-versions/${v.id}/renormalize`,{method:'POST'});const d=await r.json();setBusy('');if(!r.ok)return notify(d.detail||'派生规范化版本失败');notify(`已从 #${v.id} 原始 ZIP 创建不可变版本 #${d.parser_version_id}；原版本保持不变`);await load();await refreshed()}
 async function removeVersion(v:any){if(!confirm(`删除解析版本 #${v.id}？\n\nactive 版本和已被审查固化引用的版本无法删除；解析产物将移入可恢复归档。`))return;setBusy(`delete-${v.id}`);const r=await fetch(`/api/parser-versions/${v.id}`,{method:'DELETE'});const d=await r.json();setBusy('');if(!r.ok)return notify(d.detail||'删除解析版本失败');notify(`解析版本 #${v.id} 已删除${d.recoverable?'，产物已移入可恢复归档':''}；Trace 仍保留`);setLeft(undefined);setRight(undefined);setComparison(null);await load();await refreshed()}
 async function compare(){if(!left||!right||left===right)return notify('请选择两个不同版本');const r=await fetch(`/api/documents/${document.id}/parser-compare?left=${left}&right=${right}`);const d=await r.json();if(!r.ok)return notify(d.detail||'对比失败');setComparison(d)}
 return <div className="simple-modal parser-version-modal"><section>
  <header><div><h2>{document.name} · 解析版本</h2><p>每一版均绑定原件 SHA256、解析器/模型、参数、原始产物和 Trace，创建后不可修改；未被使用的版本可以删除。</p></div><button onClick={close}>×</button></header>
  <div className="parser-version-toolbar"><button disabled={!!busy} onClick={()=>create('pymupdf')}>＋ 新建 PyMuPDF 版本</button>{ocrProviders.map(p=><button key={p.id} className={p.kind==='mineru-local'?'primary':''} disabled={!!busy} onClick={()=>create('mineru',p)}>＋ {p.name}{p.kind==='mineru-local'?' · vlm-engine':''}</button>)}<span>{loading?'读取中…':`${items.length} 个不可变版本`}</span></div>
  <div className="parser-version-list">{items.map(v=><article className={v.is_active?'active':''} key={v.id}><header><div><b>文档内第 {v.document_version_no} 版 · {v.parser_name}</b><small>技术版本 ID {v.id} · {v.parser_version} · {v.model||v.provider_id||'—'}{v.parent_version_id?` · 派生自技术 ID ${v.parent_version_id}`:''}</small></div><em className={v.status}>{v.is_active?'ACTIVE · ':''}{v.status}</em></header><dl><div><dt>页 / 元素</dt><dd>{v.stats_json?.pages||0} / {v.stats_json?.elements||0}</dd></div><div><dt>坐标 / 表格</dt><dd>{v.stats_json?.coordinate_elements||0} / {v.stats_json?.tables||0}</dd></div><div><dt>内容覆盖</dt><dd>{v.stats_json?.canonical_content_elements||0} / {v.stats_json?.elements||0}</dd></div><div><dt>Trace</dt><dd><a href={`/trace?run=${v.trace_run_id}`} target="_blank">技术 Run ID {v.trace_run_id}</a></dd></div></dl>{v.warnings_json?.length>0&&<p>{v.warnings_json.join('；')}</p>}<footer>{v.parser_kind==='mineru'&&['ready','ready_with_warnings'].includes(v.status)&&<><a href={`/api/parser-versions/${v.id}/raw-zip`}>下载 MinerU 原始 ZIP</a><button disabled={!!busy} onClick={()=>renormalize(v)}>用当前规范化器派生新版本</button></>}<button className="danger" disabled={v.is_active||!!busy} onClick={()=>removeVersion(v)}>{v.is_active?'ACTIVE 不可删除':'删除版本'}</button><button disabled={v.is_active||!['ready','ready_with_warnings'].includes(v.status)||!!busy} onClick={()=>activate(v.id)}>{v.is_active?'当前 active':'设为 active'}</button></footer></article>)}</div>
  {items.length>1&&<section className="parser-compare"><header><b>双版本结构对比</b><div><select value={left||''} onChange={e=>setLeft(Number(e.target.value))}>{items.map(v=><option key={v.id} value={v.id}>第 {v.document_version_no} 版（技术 ID {v.id}）· {v.parser_name} · {v.provider_id}</option>)}</select><span>对比</span><select value={right||''} onChange={e=>setRight(Number(e.target.value))}>{items.map(v=><option key={v.id} value={v.id}>第 {v.document_version_no} 版（技术 ID {v.id}）· {v.parser_name} · {v.provider_id}</option>)}</select><button onClick={compare}>生成对比</button></div></header>{comparison&&<div><article><b>{comparison.left.provider_id} · {comparison.left.model}</b><pre>{comparison.left.text_preview||'无文本预览'}</pre></article><article><b>{comparison.right.provider_id} · {comparison.right.model}</b><pre>{comparison.right.text_preview||'无文本预览'}</pre></article><small>正文相似度 {Math.round((comparison.alignment?.text_similarity||0)*100)}% · 元素类型对齐 {Math.round((comparison.alignment?.element_type_jaccard||0)*100)}% · 表格单元对齐 {Math.round((comparison.alignment?.table_cell_jaccard||0)*100)}% · 页数{comparison.alignment?.page_count_match?'一致':'不一致'}<br/>元素差 {comparison.differences.element_count} · 坐标差 {comparison.differences.coordinate_count} · 表格差 {comparison.differences.table_count} · 视觉元素差 {comparison.differences.visual_count}</small></div>}</section>}
 </section></div>
}

function RiskCenter({openProject}:{openProject:(id:string)=>void}) {
 const [items,setItems]=useState<any[]>([]); const [filter,setFilter]=useState('');
 useEffect(()=>{fetch(`/api/anomalies?status=${encodeURIComponent('待复核')}${filter?`&severity=${filter}`:''}`).then(r=>r.json()).then(d=>setItems(d.items||[])).catch(()=>setItems([]));},[filter]);
 return <div className="page module-page"><div className="module-title-row"><div><h1>风险中心</h1><p>所有项目异常的集中处置入口，点击可回到项目证据链。</p></div><div className="segmented">{[['','全部'],['high','高风险'],['moderate','中风险'],['minor','低风险'],['medium','需关注'],['low','提示']].map(x=><button key={x[0]} className={filter===x[0]?'active':''} onClick={()=>setFilter(x[0])}>{x[1]}</button>)}</div></div><section className="card risk-table">{items.map(a=><button key={a.id} onClick={()=>openProject(a.project_id)}><em className={`pill ${a.severity}`}>{sevLabel[a.severity as Severity]}</em><span><b>{a.title}</b><small>{a.project_id} · {a.project_name} · {a.community}</small><p>{a.summary}</p></span><strong>{a.status}</strong><i>查看证据 ›</i></button>)}</section></div>
}

function SourcesCenter({notify}:{notify:(message:string)=>void}) {
 const [providers,setProviders]=useState<any[]>([]); const [connectors,setConnectors]=useState<any[]>([]); const [testing,setTesting]=useState('');
 useEffect(()=>{fetch('/api/providers').then(r=>r.json()).then(d=>setProviders(d.items||[]));fetch('/api/dashboard').then(r=>r.json()).then(d=>setConnectors(d.connectors||[]));},[]);
 async function test(id:string,name:string){setTesting(id);try{const r=await fetch('/api/providers/test',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({provider_id:id})});const d=await r.json();notify(`${name}：${d.ok?'连接正常':'连接失败'}${d.latency_ms?`，${d.latency_ms}ms`:''}`);}catch{notify(`${name}：测试失败`);}finally{setTesting('');}}
 return <div className="page module-page"><div className="module-title-row"><div><h1>数据源管理</h1><p>状态来自后端配置；未接入的业务系统不显示虚假记录数。</p></div><a className="primary model-config-link" href="/trace#models">配置模型与阶段路由 →</a></div><div className="connector-grid">{connectors.map(s=><article className={`card connector ${s.status}`} key={s.id}><span className="connector-logo">{s.name.slice(0,1)}</span><div><h3>{s.name}</h3><p><i></i>{s.mode}</p></div><strong>{s.records==null?'—':s.records}<small>{s.records==null?'未配置':'条记录'}</small></strong><button onClick={()=>notify(s.status==='active'?`${s.name}：已启用，数据来自项目实际上传原件`:`${s.name}：尚未配置只读 API/数据库连接`) }>{s.status==='active'?'查看状态':'接入说明'}</button></article>)}</div><h2 className="section-title">智能服务</h2><div className="model-grid">{providers.map(p=><article className="card model-card" key={p.id}><div className="model-head"><span>{p.kind.toUpperCase()}</span><em>{p.source==='reserved'?'未来本地':'当前配置'} · {p.configured?'已配置':'待配置'}</em></div><h3>{p.name}</h3><p>{p.base_url || '尚未填写服务地址'}</p><div><span>{p.kind.startsWith('mineru')?'版面解析':'OpenAI-compatible'}</span><span>结构化结果</span><span>按阶段路由</span></div><button disabled={testing===p.id||!p.configured} onClick={()=>test(p.id,p.name)}>{testing===p.id?'测试中…':'测试连接'}</button></article>)}</div></div>
}

function RulesCenter({notify}:{notify:(message:string)=>void}) {
 const [rules,setRules]=useState<any[]>([]); const [policies,setPolicies]=useState<any[]>([]); const [editor,setEditor]=useState<any>(null); const [saving,setSaving]=useState(false);
 async function load(){const [r,p]=await Promise.all([fetch('/api/rules'),fetch('/api/policies')]);setRules((await r.json()).items||[]);setPolicies((await p.json()).items||[])}
 useEffect(()=>{load().catch(()=>notify('规则与政策读取失败'))},[]);
 async function save(e:any){e.preventDefault();setSaving(true);const form=new FormData(e.currentTarget);const isRule=editor.type==='rule';const item=editor.item;const payload=isRule?{code:String(form.get('code')||''),name:String(form.get('name')||''),kind:String(form.get('kind')||''),fields:String(form.get('fields')||''),description:String(form.get('description')||''),severity:String(form.get('severity')||'medium'),enabled:form.get('enabled')==='on'}:{title:String(form.get('title')||''),clause:String(form.get('clause')||''),text:String(form.get('text')||''),source:String(form.get('source')||''),effective_date:String(form.get('effective_date')||'')||null,is_template:form.get('is_template')==='on',enabled:form.get('enabled')==='on'};const url=isRule?(item?`/api/rules/${item.code}`:'/api/rules'):(item?`/api/policies/${item.id}`:'/api/policies');try{const r=await fetch(url,{method:item?'PATCH':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const body=await r.json();if(!r.ok)throw new Error(body.detail||'保存失败');await load();setEditor(null);notify(`${isRule?'规则':'政策条款'}已保存`) }catch(err:any){notify(err.message||'保存失败')}finally{setSaving(false)}}
 async function remove(type:'rule'|'policy',item:any){const label=type==='rule'?`${item.code} ${item.name}`:item.title;if(!window.confirm(`确定删除“${label}”吗？删除后后续审查不会再执行或检索它。历史运行不会改变。`))return;const r=await fetch(type==='rule'?`/api/rules/${item.code}`:`/api/policies/${item.id}`,{method:'DELETE'});if(r.ok){await load();notify('已删除；历史运行仍保留原配置快照')}else notify((await r.json()).detail||'删除失败')}
 const enabledRules=rules.filter(r=>r.enabled); const enabledPolicies=policies.filter(p=>p.enabled);
 return <div className="page module-page rules-page"><div className="module-title-row"><div><h1>规则与政策</h1><p>{enabledRules.length} 条已启用规则 · {enabledPolicies.length} 条政策可参与检索；修改只影响后续运行。</p></div><div className="rule-toolbar"><button onClick={()=>setEditor({type:'rule',item:null})}>＋ 新增规则</button><button onClick={()=>setEditor({type:'policy',item:null})}>＋ 新增政策</button><button className="primary" onClick={()=>notify(`规则库自检：${enabledRules.length} 条规则可执行，${enabledPolicies.length} 条政策可检索`)}>运行规则库自检</button></div></div>
 <section className="card rule-kind-guide"><article><b>确定性规则</b><p>Python/SQL 对结构化事实执行金额、比例、日期顺序和完整性判断；同样输入必得同样结果。用户目前可配置“日期事件顺序”算法。</p></article><article><b>LLM 语义规则</b><p>每条规则独立调用模型，判断确认、替换、范围或措辞等语义；必须通过置信度与可定位证据门槛。</p></article><article><b>人工核验规则</b><p>不让模型替人下结论；每次运行直接创建一项人工核验任务，并显示你填写的字段和说明。</p></article><small>“系统内置 / 用户自定义”表示规则来源；“确定性 / LLM语义 / 人工核验”表示执行方式，两者不是同一个维度。</small></section>
 <section className="card severity-guide"><div><em className="pill high">高风险</em><b>重大资金或程序控制</b><p>应优先处置的明确异常。</p></div><div><em className="pill moderate">中风险</em><b>重要偏差</b><p>有较强证据且需要及时复核。</p></div><div><em className="pill minor">低风险</em><b>一般偏差</b><p>影响较低但应留痕处置。</p></div><div><em className="pill medium">需关注</em><b>尚需判断</b><p>语义候选或证据仍需人工确认。</p></div><div><em className="pill low">提示</em><b>补证提醒</b><p>不直接认定违规。</p></div><small>最终等级始终取命中规则的配置，不采信模型自行输出的等级。</small></section>
 <section className="card rules-table managed-table"><div className="doc-th"><span>规则</span><span>名称与说明</span><span>执行方式</span><span>核验字段</span><span>等级 / 状态 / 操作</span></div>{rules.map(r=><div className="doc-row" key={r.code}><b>{r.code}<small>{r.system_managed?'系统内置':'用户自定义'}</small></b><span><strong>{r.name}</strong><small>{r.description||'暂无说明'}</small></span><span>{r.kind}</span><span>{r.fields||'—'}</span><span className="manage-actions"><em className={`pill ${r.severity}`}>{sevLabel[r.severity as Severity]}</em><i>{r.enabled?'已启用':'已停用'}</i><button onClick={()=>setEditor({type:'rule',item:r})}>编辑</button><button className="danger" onClick={()=>remove('rule',r)}>删除</button></span></div>)}{!rules.length&&<div className="empty-state">尚无规则，可新增确定性、语义或人工核验规则。</div>}</section>
 <div className="policy-heading"><h2 className="section-title">政策检索库</h2><p>仅启用的条款进入政策 RAG；标题、条款分类、正文和来源均可维护。</p></div><section className="policy-grid">{policies.map(p=><article className={`card ${p.enabled?'':'disabled'}`} key={p.id}><div className="policy-card-head"><b>{p.clause}</b><em>{p.enabled?'已启用':'已停用'}</em></div><h3>{p.title}</h3><p>{p.text}</p><small>{p.source}{p.effective_date?` · ${p.effective_date}`:''}{p.is_template?' · 模板，非正式制度依据':''}</small><footer><button onClick={()=>setEditor({type:'policy',item:p})}>编辑</button><button className="danger" onClick={()=>remove('policy',p)}>删除</button></footer></article>)}{!policies.length&&<div className="empty-state">尚无政策条款。</div>}</section>
 {editor&&<div className="simple-modal rule-editor" onMouseDown={e=>e.target===e.currentTarget&&setEditor(null)}><section><header><div><h2>{editor.item?'编辑':'新增'}{editor.type==='rule'?'规则':'政策条款'}</h2><p>{editor.type==='rule'?'请选择真实执行方式；确定性规则当前支持日期事件顺序，语义规则逐条独立调用模型。':'启用后将参与后续审查的政策检索。'}</p></div><button onClick={()=>setEditor(null)}>×</button></header><form onSubmit={save}>{editor.type==='rule'?<><label>规则编号<input name="code" required disabled={!!editor.item} defaultValue={editor.item?.code||''} placeholder="例如 SCOPE-002"/></label><label>规则名称<input name="name" required defaultValue={editor.item?.name||''}/></label><label>执行方式<select name="kind" disabled={!!editor.item?.system_managed} defaultValue={editor.item?.kind||'LLM语义规则'}><option>确定性规则</option><option>LLM语义规则</option><option>人工核验规则</option></select><small>日期、金额、比例等必须选确定性；无法编码且需要理解语义时选 LLM；必须由工作人员判断时选人工。</small></label><label>风险等级<select name="severity" defaultValue={editor.item?.severity||'medium'}><option value="high">高风险</option><option value="moderate">中风险</option><option value="minor">低风险</option><option value="medium">需关注</option><option value="low">提示</option></select></label><label className="wide">核验字段<input name="fields" defaultValue={editor.item?.fields||''} placeholder="日期规则示例：设备到货、调试、竣工验收；语义规则示例：替换说明、建设单位确认"/><small>确定性日期规则：最后一个字段是对照事件，前面的字段依次比较。</small></label><label className="wide">判定说明<textarea name="description" rows={5} defaultValue={editor.item?.description||''} placeholder="写明对象、触发条件、通过/异常条件。日期规则必须包含早于、晚于、先于或不晚于。"/><small>语义规则推荐：当【对象】发生【事件】且资料明确【缺失/未确认】时，判为异常；需要引用哪些原文证据；证据不足时不命中。</small></label></>:<><label>政策标题<input name="title" required defaultValue={editor.item?.title||''}/></label><label>条款分类<input name="clause" required defaultValue={editor.item?.clause||''} placeholder="例如 工程变更"/></label><label>来源<input name="source" required defaultValue={editor.item?.source||''}/></label><label>生效日期<input name="effective_date" type="date" defaultValue={editor.item?.effective_date||''}/></label><label className="wide">条款正文<textarea name="text" required rows={6} defaultValue={editor.item?.text||''}/></label><label className="check"><input name="is_template" type="checkbox" defaultChecked={!!editor.item?.is_template}/> 标记为模板（非正式依据）</label></>}<label className="check"><input name="enabled" type="checkbox" defaultChecked={editor.item?!!editor.item.enabled:true}/> 启用</label><footer><button type="button" onClick={()=>setEditor(null)}>取消</button><button className="primary" disabled={saving}>{saving?'保存中…':'保存'}</button></footer></form></section></div>}
 </div>
}
